<script setup lang="ts">import {ref,onShow} from 'vue';import {api} from '../../lib/api';const shops=ref<any[]>([]),loading=ref(true);async function load(){loading.value=true;try{shops.value=await api.request('/shops')}catch(e:any){uni.showToast({title:e.message,icon:'none'})}finally{loading.value=false}}function open(id:string){uni.navigateTo({url:`/pages/shop/index?id=${id}`})}onShow(load)</script>
<template><view class="page"><view class="hero"><view class="eyebrow">CAMPUS FOOD STREET</view><view class="title">今天想吃点什么？</view><view class="sub">附近好店 · 自取更快 · 价格透明</view></view><view class="search">⌕ <text>搜索店铺或菜品</text></view><view class="section"><view class="section-title">附近店铺 <text>{{shops.length}} 家营业中</text></view><view v-if="loading" class="empty">正在加载美味…</view><view v-else-if="!shops.length" class="empty">暂无营业店铺，请先用演示商户登录初始化</view><view v-for="s in shops" :key="s.id" class="shop" @click="open(s.id)"><view class="logo">{{s.name.slice(0,1)}}</view><view class="shop-main"><view class="shop-name">{{s.name}} <text class="open">营业中</text></view><view class="notice">{{s.notice}}</view><view class="meta">校园自取 · 约 15 分钟</view></view><text class="arrow">›</text></view></view></view></template>
<style scoped>.page{padding:42rpx 32rpx}.hero{padding:20rpx 4rpx 30rpx}.eyebrow{font-size:20rpx;letter-spacing:4rpx;color:#f36d3b;font-weight:700}.title{font-size:52rpx;font-weight:800;margin-top:18rpx}.sub{color:#9b9289;margin-top:14rpx}.search{background:#fff;padding:26rpx 30rpx;border-radius:24rpx;color:#f36d3b;box-shadow:0 10rpx 35rpx #e8d9cc55}.search text{color:#aaa;margin-left:14rpx}.section{margin-top:54rpx}.section-title{font-size:36rpx;font-weight:700}.section-title text{float:right;font-size:22rpx;color:#aaa;font-weight:400;margin-top:12rpx}.shop{background:#fff;margin-top:22rpx;border-radius:28rpx;padding:28rpx;display:flex;align-items:center;box-shadow:0 8rpx 28rpx #e8d9cc40}.logo{width:100rpx;height:100rpx;border-radius:26rpx;background:#ffdfc8;color:#d95425;font-size:48rpx;font-weight:800;display:flex;align-items:center;justify-content:center}.shop-main{flex:1;margin-left:24rpx}.shop-name{font-weight:700;font-size:30rpx}.open{font-size:20rpx;color:#42a56c;background:#e4f6ea;padding:5rpx 12rpx;border-radius:20rpx;margin-left:10rpx}.notice{font-size:24rpx;color:#6f655e;margin-top:12rpx}.meta{font-size:21rpx;color:#aaa;margin-top:10rpx}.arrow{font-size:46rpx;color:#bbb}.empty{text-align:center;color:#aaa;padding:80rpx 0}</style>
